{
  "role": "user",
  "content": [
    { "type": "text", "text": "Summarize this config for me." },
    {
      "type": "resource",
      "resource": {
        "uri": "file:///etc/app/config.yaml",
        "mimeType": "text/yaml",
        "text": "server:\n  port: 8080\n  timeout: 30s\n"
      }
    }
  ]
}

{
  "uri": "file:///var/log/app/latest.log",
  "name": "Latest application log",
  "description": "Most recent 24 hours of application log output",
  "mimeType": "text/plain"
}

